-- Page-side half of the tenant_id=1 fix (see V223 for the workflow_definition
-- half). tenant_id=1 has its OWN page_definition rows for aria:front-gate-create
-- and aria:dispatch-vehicle-details, completely separate from the product-default
-- (tenant_id=-1) rows — same per-tenant fork situation V223 already found for
-- workflow_definition. Only the current PUBLISHED version (pd.current_version_id)
-- is touched; an in-progress DRAFT version on aria:dispatch-vehicle-details is
-- left alone since it isn't what live traffic uses.
--
-- Tenant 1's own customizations are preserved as-is: "Vehicle Movement Type"
-- label, vehicle-number/phone validation patterns, and dispatch-vehicle-details'
-- cardFields/secondLineFields queue display config and field ordering
-- (flowVariantCode/loadingType at the end of the field list).
--
-- Tenant 1 only ever operates these 3 flows (no TankerOutbound/PackLoading/
-- FGLoading/IntTransferIn-Out/ThirdPartyIn-Out/EwayBill traffic), so unlike the
-- product-default fix, the Flow Variant field is removed from
-- aria:front-gate-create ENTIRELY here (not just filtered down) — every Gate
-- Pass save on this page is now the plain, non-workflow save, so a single
-- button replaces the old workflow.transition one. dispatch-vehicle-details
-- still gains the flowVariantChoice selector + picker/button changes to become
-- the workflow's start point. Tenant 1's front-gate-create has no
-- "Gate Passes In Progress" queue section and no securityOfficerName field, so
-- neither needs any handling here (unlike the product-default page).

UPDATE page_version pv JOIN page_definition pd ON pd.current_version_id = pv.id
   SET pv.body_json = '{"kind":"layout","schemaVersion":2,"slug":"aria:front-gate-create","title":"Front Gate — Vehicle Intake","status":"published","version":1,"roles":["FrontGate","TenantAdmin"],"dataSources":[],"streams":[],"entity":"GatePass","layout":[{"kind":"Grid","columns":12,"gap":16,"children":[{"kind":"Section","title":"New Vehicle Intake","span":12,"subtitle":"Capture the vehicle at the gate, then Create Gate Pass to start the selected flow.","children":[{"kind":"Form","submitLabel":"","bindings":{"fields":[{"name":"loading_type","label":"Vehicle Movement Type","required":true,"type":"select","optionsSource":{"type":"entity","entity":"LoadingType","valueField":"code","labelField":"display_name"}},{"name":"vehicle_no","label":"Vehicle No","type":"text","required":true,"placeholder":"TN86J6790","uppercase":true,"pattern":"^[A-Z]{2}-?[0-9]{2}-?[A-Z]{1,2}-?[0-9]{4}$","patternError":"Enter valid vehicle number"},{"name":"vehicle_category","label":"Vehicle Category","required":true,"type":"select","optionsSource":{"type":"entity","entity":"VehicleCategory","valueField":"code","labelField":"display_name"}}]},"children":[{"kind":"WorkflowActionButton","label":"Create Gate Pass","action":"gatepass.create","entity":"GatePass","color":"primary","onSuccessOpen":{"page":"aria:gate-pass-slip","lookupEntity":"GatePass","lookupField":"id","param":"id"}}]}]}]}]}'
 WHERE pd.code = 'aria:front-gate-create' AND pd.tenant_id = 1 AND pv.body_json NOT LIKE '%"action":"gatepass.create"%';

UPDATE page_version pv JOIN page_definition pd ON pd.current_version_id = pv.id
   SET pv.body_json = '{"kind":"layout","schemaVersion":2,"dataSources":[{"id":"dispatchQueue","kind":"rest","method":"GET","url":"/api/workflow/queue-for-page?pageCode=aria:dispatch-vehicle-details"}],"layout":[{"kind":"Section","title":"Dispatch Queue (Open)","fields":[{"kind":"WorkflowQueueList","persona":"Dispatch","dataSource":"dispatchQueue","pageSize":25,"cardFields":[],"fillFormOnSelect":true,"priorityShading":true,"secondLineFields":["gpNumber","flowVariantCode"]}]},{"kind":"Section","title":"Vehicle & Dispatch Details","fields":[{"kind":"FormField","type":"select","name":"vehicleNo","label":"Vehicle Number","required":true,"placeholder":"Select vehicle awaiting dispatch entry","optionsSource":{"type":"datasource","spec":{"type":"entity","entity":"GatePass","joins":[{"entity":"WorkflowInstance","as":"wi","on":"gate_pass.workflow_instance_id = wi.id"}],"filter":{"or":[{"and":[{"field":"wi.assigned_role","op":"eq","value":"Dispatch"},{"field":"wi.status","op":"eq","value":"OPEN"}]},{"and":[{"field":"workflow_instance_id","op":"isnull"},{"field":"loading_type","op":"eq","value":"UN_LOADING"}]}]},"select":["id","vehicle_no"],"sort":[{"field":"vehicle_no","dir":"asc"}]},"valueField":"vehicle_no","labelField":"vehicle_no"},"onChangeFill":{"flowVariantCode":"flow_variant_code","loadingType":"loading_type","instanceId":"workflow_instance_id"}},{"kind":"FormField","type":"select","name":"ownershipType","label":"Ownership","options":["OWN VEHICLE","HIRED VEHICLE"]},{"kind":"FormField","type":"text","name":"driverName","label":"Driver Name"},{"kind":"FormField","type":"text","name":"driverPhone","label":"Driver Contact","pattern":"^[0-9]{10}$","patternError":"Enter a valid 10-digit phone number","maxLength":10,"digitsOnly":true},{"kind":"FormField","type":"text","name":"brokerName","label":"Broker Details","visibleWhen":"#form.flowVariantCode == \'M10.TankerOutbound\' || #form.flowVariantCode == \'M10.TankerInbound\' || #form.flowVariantCode == \'M10.PackUnload\' || #form.flowVariantChoice == \'M10.TankerInbound\' || #form.flowVariantChoice == \'M10.PackUnload\'"},{"kind":"FormField","type":"text","name":"invoiceNo","label":"Invoice No","visibleWhen":"#form.flowVariantCode == \'M10.TankerOutbound\' || #form.flowVariantCode == \'M10.TankerInbound\' || #form.flowVariantCode == \'M10.PackUnload\' || #form.flowVariantChoice == \'M10.TankerInbound\' || #form.flowVariantChoice == \'M10.PackUnload\'"},{"kind":"FormField","type":"number","name":"invoiceQty","label":"Invoice Qty","visibleWhen":"#form.flowVariantCode == \'M10.TankerOutbound\' || #form.flowVariantCode == \'M10.TankerInbound\' || #form.flowVariantCode == \'M10.PackUnload\' || #form.flowVariantChoice == \'M10.TankerInbound\' || #form.flowVariantChoice == \'M10.PackUnload\'"},{"kind":"FormField","type":"text","name":"vendorName","label":"Vendor Details","visibleWhen":"#form.flowVariantCode == \'M10.TankerOutbound\' || #form.flowVariantCode == \'M10.TankerInbound\' || #form.flowVariantCode == \'M10.PackUnload\' || #form.flowVariantChoice == \'M10.TankerInbound\' || #form.flowVariantChoice == \'M10.PackUnload\'"},{"kind":"FormField","type":"text","name":"oilRmItem","label":"Oil RM Details","visibleWhen":"#form.flowVariantCode == \'M10.TankerOutbound\' || #form.flowVariantCode == \'M10.TankerInbound\' || #form.flowVariantCode == \'M10.ReturnStockIn\' || #form.flowVariantChoice == \'M10.TankerInbound\' || #form.flowVariantChoice == \'M10.ReturnStockIn\'"},{"kind":"FormField","type":"text","name":"tankerNo","label":"Tanker Number","visibleWhen":"#form.flowVariantCode == \'M10.TankerOutbound\' || #form.flowVariantCode == \'M10.TankerInbound\' || #form.flowVariantChoice == \'M10.TankerInbound\'"},{"kind":"FormField","type":"select","name":"poVerified","label":"PO Verified","options":["YES","NO - MANAGER APPROVAL"],"visibleWhen":"#form.flowVariantCode == \'M10.TankerOutbound\' || #form.flowVariantCode == \'M10.TankerInbound\' || #form.flowVariantCode == \'M10.PackUnload\' || #form.flowVariantChoice == \'M10.TankerInbound\' || #form.flowVariantChoice == \'M10.PackUnload\'"},{"kind":"FormField","type":"text","name":"poOverrideReason","label":"Reason (if PO not verified)","visibleWhen":"(#form.flowVariantCode == \'M10.TankerOutbound\' || #form.flowVariantCode == \'M10.TankerInbound\' || #form.flowVariantCode == \'M10.PackUnload\' || #form.flowVariantChoice == \'M10.TankerInbound\' || #form.flowVariantChoice == \'M10.PackUnload\') && #form.poVerified != \'YES\'","requiredWhen":"(#form.flowVariantCode == \'M10.TankerOutbound\' || #form.flowVariantCode == \'M10.TankerInbound\' || #form.flowVariantCode == \'M10.PackUnload\' || #form.flowVariantChoice == \'M10.TankerInbound\' || #form.flowVariantChoice == \'M10.PackUnload\') && #form.poVerified != \'YES\'"},{"kind":"FormField","type":"text","name":"dispatchOfficerName","label":"Dispatch Front Officer Name","visibleWhen":"#form.flowVariantCode == \'M10.TankerOutbound\' || #form.flowVariantCode == \'M10.TankerInbound\' || #form.flowVariantCode == \'M10.PackUnload\' || #form.flowVariantChoice == \'M10.TankerInbound\' || #form.flowVariantChoice == \'M10.PackUnload\'"},{"kind":"FormField","type":"text","name":"transportName","label":"Transport Name","visibleWhen":"#form.flowVariantCode == \'M10.PackLoading\' || #form.flowVariantCode == \'M10.FGLoading\' || #form.flowVariantCode == \'M10.TankerOutbound\'"},{"kind":"FormField","type":"textarea","name":"packingFgStockDetails","label":"Packing / FG Stock Details","visibleWhen":"#form.flowVariantCode == \'M10.PackLoading\' || #form.flowVariantCode == \'M10.FGLoading\' || #form.flowVariantCode == \'M10.PackUnload\' || #form.flowVariantChoice == \'M10.PackUnload\'"},{"kind":"FormField","type":"number","name":"invoiceReturnCount","label":"Invoice Stock Return Count","visibleWhen":"#form.flowVariantCode == \'M10.ReturnStockIn\' || #form.flowVariantChoice == \'M10.ReturnStockIn\'"},{"kind":"FormField","type":"number","name":"boxWeightKg","label":"Box Weight (kg)","visibleWhen":"#form.flowVariantCode == \'M10.ReturnStockIn\' || #form.flowVariantChoice == \'M10.ReturnStockIn\'"},{"kind":"FormField","type":"text","name":"oilType","label":"Oil Type","visibleWhen":"#form.flowVariantCode == \'M10.ReturnStockIn\' || #form.flowVariantChoice == \'M10.ReturnStockIn\'"},{"kind":"FormField","type":"text","name":"flowVariantCode","label":"Flow Variant","disabled":true},{"kind":"FormField","type":"text","name":"loadingType","label":"Loading Type","disabled":true},{"kind":"FormField","type":"select","name":"flowVariantChoice","label":"Flow Variant","visibleWhen":"(#form.instanceId == null || #form.instanceId == \'\') && #form.loadingType == \'UN_LOADING\'","requiredWhen":"(#form.instanceId == null || #form.instanceId == \'\') && #form.loadingType == \'UN_LOADING\'","optionsSource":{"type":"datasource","spec":{"type":"entity","entity":"FlowVariant","filter":{"field":"code","op":"in","value":["M10.TankerInbound","M10.PackUnload","M10.ReturnStockIn"]},"select":["code","display_name"],"sort":[{"field":"display_name","dir":"asc"}]},"valueField":"code","labelField":"display_name"}},{"kind":"WorkflowActionButton","label":"Save Vehicle Details","action":"workflow.transition","instanceId":"{{form.instanceId}}","workflowCode":"{{form.flowVariantChoice}}","trigger":"page.submitted","variant":"primary"}]}],"entity":"DispatchVehicleDetail"}'
 WHERE pd.code = 'aria:dispatch-vehicle-details' AND pd.tenant_id = 1 AND pv.body_json NOT LIKE '%flowVariantChoice%';
